import { useState } from 'react';
import Navbar from '../components/Navbar';
import Sidebar from '../components/Sidebar';
import ProgressCard from '../components/ProgressCard';
import CourseCard from '../components/CourseCard';

const StudentDashboard = () => {
  const [courses, setCourses] = useState([
    {
      id: 1,
      title: 'Introduction to React',
      description: 'Learn the fundamentals of React including components, state, and props.',
      progress: 65,
      enrolled: true,
    },
    {
      id: 2,
      title: 'Advanced JavaScript',
      description: 'Deep dive into advanced JavaScript concepts like closures and prototypes.',
      progress: 30,
      enrolled: true,
    },
    {
      id: 3,
      title: 'Tailwind CSS Basics',
      description: 'Master utility-first CSS with Tailwind for rapid UI development.',
      progress: 0,
      enrolled: false,
    },
    {
      id: 4,
      title: 'Node.js Fundamentals',
      description: 'Learn server-side JavaScript with Node.js and Express.',
      progress: 0,
      enrolled: false,
    },
  ]);

  const enrollCourse = (courseId) => {
    setCourses(
      courses.map((course) =>
        course.id === courseId ? { ...course, enrolled: true } : course
      )
    );
  };

  return (
    <div className="h-screen bg-gray-50 overflow-hidden flex flex-col">
      <Navbar />
      <div className="flex flex-1 overflow-hidden">
        <Sidebar />
        <main className="flex-1 overflow-y-auto focus:outline-none">
          <div className="py-6">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 md:px-8">
              <h1 className="text-2xl font-semibold text-gray-900">Dashboard</h1>
            </div>
            <div className="max-w-7xl mx-auto px-4 sm:px-6 md:px-8">
              <div className="py-4">
                <div className="mb-8">
                  <h2 className="text-lg font-medium text-gray-900 mb-4">My Progress</h2>
                  <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3">
                    <ProgressCard
                      title="Overall Completion"
                      value={45}
                      color="indigo"
                    />
                    <ProgressCard
                      title="Courses Enrolled"
                      value={courses.filter(c => c.enrolled).length}
                      max={courses.length}
                      color="green"
                    />
                    <ProgressCard
                      title="Avg. Progress"
                      value={
                        courses.filter(c => c.enrolled).length > 0
                          ? courses
                              .filter(c => c.enrolled)
                              .reduce((sum, course) => sum + course.progress, 0) /
                            courses.filter(c => c.enrolled).length
                          : 0
                      }
                      color="blue"
                    />
                  </div>
                </div>

                <div>
                  <div className="flex justify-between items-center mb-4">
                    <h2 className="text-lg font-medium text-gray-900">Available Courses</h2>
                  </div>
                  <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3">
                    {courses.map((course) => (
                      <CourseCard
                        key={course.id}
                        course={course}
                        onEnroll={enrollCourse}
                      />
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default StudentDashboard;
